export const inviteLogic = kea<inviteLogicType>([
    path(['scenes', 'organization', 'Settings', 'inviteLogic']),
    connect(() => ({
        values: [preflightLogic, ['preflight']],
    })),
    actions({
        showInviteModal: true,
        hideInviteModal: true,
